using System;

// snake_case fields mirror data/generated/bestiary.json for JsonUtility (see CepaMapData).
#pragma warning disable IDE1006

namespace CepaCero.AI
{
    /// <summary>Raw `cepacero.bestiary` v1 document generated by tools/datagen from docs/bestiario.md.</summary>
    [Serializable]
    public sealed class BestiaryData
    {
        public string format;
        public int version;
        public string source;
        public ZombieDefinition[] zombies;
    }

    /// <summary>Stats of one zombie type. Units: tiles, tiles/s, seconds. Do not edit by hand: edit docs/bestiario.md.</summary>
    [Serializable]
    public sealed class ZombieDefinition
    {
        public string id;
        public string name;
        public string tier;
        public bool mvp;
        public float size_tiles;
        public int health;
        public float health_per_extra_player;
        public float speed;
        public int damage;
        public string damage_type;
        public float attack_interval;
        public float attack_range;
        public int structure_damage;
        public MaterialMultipliers structure_multipliers;
        public float detect_sight;
        public float detect_hearing;
        public string[] behavior;
        public DamageMultipliers damage_taken;
        public float armor_front_arc_degrees;
        public float armor_front_multiplier;
        public string spawn_condition;
        public AbilityData[] abilities;
        public string weakness;
        public LootEntry[] loot;
        public string visual;
        public string audio;

        /// <summary>Health scaled for the party size (bosses get tougher with more players).</summary>
        public int HealthFor(int players)
        {
            int extra = Math.Max(0, players - 1);
            return (int)Math.Round(health * (1.0 + health_per_extra_player * extra), MidpointRounding.AwayFromZero);
        }

        public bool HasBehavior(string tag) => behavior != null && Array.IndexOf(behavior, tag) >= 0;

        /// <summary>Ability record by type ("scream", "charge"...), or null.</summary>
        public AbilityData GetAbility(string type)
        {
            if (abilities == null)
            {
                return null;
            }
            foreach (AbilityData a in abilities)
            {
                if (a.type == type)
                {
                    return a;
                }
            }
            return null;
        }
    }

    /// <summary>
    /// One special ability with a fixed set of parameters; each ability uses
    /// the ones it needs (see docs/bestiario.md and tools/datagen).
    /// </summary>
    [Serializable]
    public sealed class AbilityData
    {
        public string type;
        public float cooldown;
        public float windup;
        public float radius;
        public float seconds;
        public float speed;
        public float damage;
        public float multiplier = 1f;
        public float knockback;
        public int count;
        public float heal;
        public float dps;
        public string[] breaks;
        public string[] stunned_by;

        public bool Breaks(string material) => breaks != null && Array.IndexOf(breaks, material) >= 0;

        public bool IsStunnedBy(string material) => stunned_by != null && Array.IndexOf(stunned_by, material) >= 0;
    }

    [Serializable]
    public sealed class MaterialMultipliers
    {
        public float wood = 1f;
        public float metal = 1f;
        public float concrete = 1f;
    }

    [Serializable]
    public sealed class DamageMultipliers
    {
        public float blunt = 1f;
        public float sharp = 1f;
        public float ballistic = 1f;
        public float fire = 1f;
        public float acid = 1f;
    }

    [Serializable]
    public sealed class LootEntry
    {
        public string item;
        public int min;
        public int max;
        public float chance;
    }
}
